"""Exchange rates from the rates service."""
import json
import urllib.request

RATES_URL = "https://rates.example.com/v1/latest?base=USD&symbol={code}"


def _http_get(url):
    with urllib.request.urlopen(url, timeout=10) as resp:
        return resp.read().decode("utf-8")


def _download(code):
    payload = json.loads(_http_get(RATES_URL.format(code=code)))
    return float(payload["rate"])


_cache = {}


def get_rate(code):
    """USD -> `code` exchange rate, e.g. get_rate("EUR"). Cached per currency."""
    key = code.upper()
    if key not in _cache:
        _cache[key] = _download(key)
    return _cache[key]

